-- Create "knowledge_comments" table
CREATE TABLE `knowledge_comments` (`id` varchar(32) NOT NULL, `created_at` datetime(6) NOT NULL, `team_id` varchar(32) NOT NULL, `document_id` varchar(32) NOT NULL, `parent_id` varchar(32) NOT NULL DEFAULT "", `author_id` varchar(32) NOT NULL, `version` bigint NOT NULL, `quote` varchar(2000) NOT NULL DEFAULT "", `anchor` varchar(800) NOT NULL DEFAULT "", `body` longtext NOT NULL, `resolved_by` varchar(32) NOT NULL DEFAULT "", `resolved_at` datetime(6) NULL, PRIMARY KEY (`id`), INDEX `knowledgecomment_author_id` (`author_id`), INDEX `knowledgecomment_document_id_created_at` (`document_id`, `created_at`)) CHARSET utf8mb4 COLLATE utf8mb4_bin;
